# Вариант А: кино и кафе. Формат задачи см. build.py
V = 'A'
TASKS = [
dict(n=1, pts=0.5, title='Билет в кино', topics='if / elif / else, not in, or',
 text='В окне уже заданы список `sessions` и три фразы: `none_msg`, `cheap_msg`, `full_msg`. Вводятся время сеанса и возраст зрителя.\n\nЕсли такого сеанса нет в списке, напечатайте `none_msg`. Если сеанс есть и зрителю меньше 12 лет или 60 и больше, напечатайте `cheap_msg`. Во всех остальных случаях напечатайте `full_msg`.',
 fin='Первая строка — время сеанса, вторая — возраст (целое число).', fout='Одна из трёх фраз.',
 pre="sessions = ['10:00', '14:00', '18:00']\nnone_msg = 'Такого сеанса нет'\ncheap_msg = 'Льготный билет'\nfull_msg = 'Полный билет'",
 inputs=[['10:00','8'],['14:00','30'],['20:00','10'],['18:00','60'],['10:00','12'],['14:00','59'],['18:00','11']],
 sol="time = input()\nage = int(input())\n\nif time not in sessions:\n    print(none_msg)\nelif age < 12 or age >= 60:\n    print(cheap_msg)\nelse:\n    print(full_msg)\n",
 hint='Сначала отсеките несуществующие сеансы (`not in`), потом проверьте возраст через `or`, остальное — `else`. Возраст — строка, нужен `int`.',
 idea='Три исхода — цепочка `if / elif / else`: нет сеанса; льгота по возрасту; полный билет.',
 steps=['`time = input()` читает сеанс, `age = int(input())` читает возраст и сразу делает его числом.','`time not in sessions` — первая проверка: если сеанса нет, возраст не важен.','`age < 12 or age >= 60` — льгота, если верно **хотя бы одно** из двух условий.','`else` — полный билет.'],
 mist=['Написали `age < 12 and age >= 60`: оба условия сразу не бывают верны, льготы не будет ни у кого.','Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.','Границы: 12 лет уже платят полностью, 60 лет — уже льгота; перепутали `<` и `<=`.']),
dict(n=2, pts=1, title='Недорогие блюда', topics='while True, break, split, список',
 text='Вводятся строки вида `блюдо:цена` (цена — целое число), пока не будет введено слово `END`.\n\nНапечатайте список блюд, которые стоят **не дороже 300**, в порядке ввода. Если таких нет, напечатайте пустой список.',
 fin='Строки `блюдо:цена`, последняя строка — `END`.', fout='Список блюд в квадратных скобках, как печатает `print(список)`.',
 pre='',
 inputs=[['Борщ:250','Стейк:900','Суп:300','END'],['END'],['Пицца:450','Салат:301','END'],['Чай:80','Кофе:120','Пирог:200','END'],['Паста:300','END']],
 sol="cheap = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    dish, price = line.split(':')\n    if int(price) <= 300:\n        cheap.append(dish)\n\nprint(cheap)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `dish, price = line.split(":")`. Цена — строка, нужен `int`. «Не дороже» — это `<=`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`cheap = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём цикл.','`line == "END"` → `break`: выходим, не обрабатывая слово `END`.','`dish, price = line.split(":")` — две части строки в две переменные.','`int(price) <= 300` — «не дороже» включает ровно 300.'],
 mist=['Список создан внутри цикла — в конце останется только последнее блюдо.','Не сделали `int(price)`: сравнение строки с числом — ошибка `TypeError`.','Поставили `<`: блюдо ровно за 300 пропадёт.']),
dict(n=3, pts=0.5, title='Список гостей', topics='split(", "), in, remove, append',
 text='В первой строке имена гостей через «запятая + пробел». Во второй — имя одного человека.\n\nЕсли он уже в списке, он отменил бронь — удалите его из списка. Если его нет — добавьте в конец. Напечатайте список.',
 fin='Первая строка — имена через `, `. Вторая — одно имя.', fout='Список имён в квадратных скобках.',
 pre='',
 inputs=[['Аня, Борис, Вера','Борис'],['Аня, Борис','Глеб'],['Дима','Дима'],['Зоя, Ира','зоя'],['Олег, Пётр, Рита','Рита']],
 sol="guests = input().split(', ')\nname = input()\n\nif name in guests:\n    guests.remove(name)\nelse:\n    guests.append(name)\n\nprint(guests)\n",
 hint='Строку с именами разбейте `split(", ")`. Если имя есть (`in`) — `remove`, иначе — `append`.',
 idea='Превращаем строку в список и, смотря по наличию имени, удаляем его или добавляем.',
 steps=['`input().split(", ")` — строка превращается в список имён.','`name in guests` — истина, если человек уже есть в списке.','`remove` удаляет, `append` добавляет в конец; оба меняют сам список.','`print(guests)` — один раз, после `if`.'],
 mist=['`split()` без аргумента: запятые останутся в кусках имён.','`remove` для имени, которого нет, даёт `ValueError` — поэтому сначала проверяем `in`.','Результат `append` или `remove` присвоили переменной: получится `None`.']),
dict(n=4, pts=1, title='Хорошие фильмы', topics='два списка, range(len()), float',
 text='В первой строке названия фильмов через пробел, во второй — их оценки (числа, бывают дробные) в том же порядке. В третьей — оценка, выше которой фильм считается хорошим.\n\nНапечатайте названия фильмов с оценкой **строго выше** этой, каждое с новой строки.',
 fin='Три строки: названия, оценки, граница.', fout='Названия по одному на строке или пустой вывод.',
 pre='',
 inputs=[['Дюна Титаник Хатико Зелёнка','8.5 7.9 8.1 6.4','8'],['А Б','7 7.5','7.5'],['Один','9','8.9'],['Х У Ф','5 6 7','7'],['Лента Кино','8.0 8.0','7']],
 sol="films = input().split()\nmarks = input().split()\nlimit = float(input())\n\nfor i in range(len(films)):\n    if float(marks[i]) > limit:\n        print(films[i])\n",
 hint='Фильмы и оценки лежат в двух списках, связь — одинаковый номер. Переберите номера через `range(len(...))`. Оценки — строки, нужен `float`.',
 idea='Идём по номерам: по номеру берём и фильм, и оценку, сравниваем оценку с границей.',
 steps=['`films` и `marks` — списки **строк**; оценку берём как `float(marks[i])`.','`range(len(films))` — номера 0, 1, 2, …','`float(marks[i]) > limit` — «строго выше», то есть `>`.','Печатаем `films[i]` — фильм с тем же номером.'],
 mist=['`>=` вместо `>`: фильм ровно с граничной оценкой попадёт зря.','Использовали `int` для оценки `8.5`: будет `ValueError`.','Напечатали `marks[i]` вместо `films[i]`.']),
dict(n=5, pts=0.75, title='Зрители двух залов', topics='множества, симметричная разность',
 text='Две строки: имена зрителей первого зала и второго (через пробел).\n\nНапечатайте, сколько людей побывало **ровно в одном** из залов (то есть не в обоих).',
 fin='Две строки, имена через пробел.', fout='Одно число.',
 pre='',
 inputs=[['Аня Борис Вера','Борис Глеб'],['Омск','Омск'],['А Б В','Г Д'],['Зоя','Зоя Ира Лев'],['Паша Рита','Рита Паша']],
 sol="first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first ^ second))\n",
 hint='Превратите обе строки во множества. «Ровно в одном» — симметрическая разность `^`.',
 idea='Симметрическая разность хранит тех, кто есть только в одном из двух множеств.',
 steps=['`set(input().split())` — строка → список → множество.','`first ^ second` — элементы, которые есть в одном множестве, но не в обоих.','`len(...)` — сколько их.'],
 mist=['`|` вместо `^`: посчитаются и те, кто был в обоих залах.','`&` вместо `^`: получатся только те, кто был в обоих.','Сложили `len(first) + len(second)`: общий зритель посчитается дважды.']),
dict(n=6, pts=1.25, title='Блюда только первого стола', topics='множества, разность и пересечение',
 text='Три строки с названиями блюд через запятую **без пробела** (в названиях пробелы бывают): заказ первого стола; заказ второго стола; меню кафе.\n\nНапечатайте, сколько блюд заказал **только первый стол** (второй их не брал) и которые **есть в меню**.',
 fin='Три строки, блюда через запятую.', fout='Одно число.',
 pre='',
 inputs=[['Борщ,Суп,Чай','Чай,Пирог','Борщ,Суп,Чай,Пирог'],['Салат,Хлеб','Салат','Салат,Хлеб'],['Х','Х','Х'],['Пицца,Паста','Кофе','Паста,Кофе'],['Рыба фри,Чай','Чай','Чай,Рыба фри,Торт']],
 sol="first = set(input().split(','))\nsecond = set(input().split(','))\nmenu = set(input().split(','))\n\nonly = first - second\nprint(len(only & menu))\n",
 hint='«Только первый стол» — разность `-`. Потом пересеките результат `&` с меню.',
 idea='Сначала блюда первого стола, которых нет у второго (`-`), затем оставляем только те, что есть в меню (`&`).',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Без аргумента названия с пробелами разорвутся.','`first - second` — блюда первого стола, которых нет у второго.','`only & menu` — из них только те, что есть в меню.','`len(...)` — сколько их.'],
 mist=['`split()` вместо `split(",")`: «Рыба фри» разорвётся на два блюда.','`second - first` вместо `first - second`: получится про второй стол.','`^` вместо `-`: попадут и блюда, которые брал только второй стол.']),
dict(n=7, pts=0.75, title='Блюда в рамках бюджета', topics='словарь, перебор ключей',
 text='В окне задан словарь `menu`: блюдо → цена. Вводится бюджет (целое число).\n\nНапечатайте блюда, цена которых **не больше** бюджета, каждое с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — бюджет (целое число).', fout='Названия по одному на строке или пустой вывод.',
 pre="menu = {'чай': 80, 'кофе': 150, 'борщ': 250, 'стейк': 900, 'салат': 220, 'пирог': 130}",
 inputs=[['150'],['80'],['1000'],['50'],['220']],
 sol="budget = int(input())\n\nfor dish in menu:\n    if menu[dish] <= budget:\n        print(dish)\n",
 hint='Цикл `for dish in menu` перебирает **ключи** (блюда). Цена берётся как `menu[dish]`. Введённый бюджет — строка, нужен `int`.',
 idea='Идём по блюдам и печатаем те, у которых цена не больше бюджета.',
 steps=['`budget = int(input())` — цены в словаре числа, значит и бюджет нужно сделать числом.','`for dish in menu:` — переменная `dish` по очереди получает каждое блюдо.','`menu[dish] <= budget` — «не больше», то есть `<=`.','Печатаем `dish`, а не цену.'],
 mist=['Забыли `int(...)`: сравнение `80 <= "150"` — ошибка `TypeError`.','`<` вместо `<=`: блюдо с ценой ровно как бюджет пропадёт.','Напечатали `menu[dish]`: получится цена вместо названия.']),
dict(n=8, pts=1.25, title='Столы с хорошими чаевыми', topics='словарь списков, sum',
 text='В окне задан словарь `tables`: стол → список чаевых за четыре дня (в рублях). Вводится порог.\n\nНапечатайте столы, у которых **сумма** чаевых **строго больше** порога, каждый с новой строки, в порядке словаря.',
 fin='Одна строка — порог (целое число).', fout='Названия столов по одному на строке или пустой вывод.',
 pre="tables = {'Первый': [100, 250, 0, 300], 'Второй': [50, 40, 60, 30], 'Третий': [500, 100, 200, 400], 'Четвёртый': [120, 130, 100, 150]}",
 inputs=[['300'],['180'],['650'],['1200'],['0']],
 sol="limit = int(input())\n\nfor table in tables:\n    if sum(tables[table]) > limit:\n        print(table)\n",
 hint='Сумма чаевых стола — `sum(tables[table])`. Сравните её с порогом.',
 idea='Для каждого ключа берём список, считаем сумму и сравниваем с порогом.',
 steps=['`tables[table]` — список чаевых стола.','`sum(...)` — сумма за четыре дня.','`> limit` — строго больше порога.','Печатаем `table`, а не сумму.'],
 mist=['Сравнили `tables[table] > limit`: список с числом сравнивать нельзя.','`>=` вместо `>`: стол с суммой ровно как порог попадёт зря.','Напечатали `sum(...)` вместо названия стола.'],
 trace='Первый: 100 + 250 + 0 + 300 = 650. Второй: 180. Третий: 1200. Четвёртый: 500. При пороге 300 строго больше у Первого, Третьего и Четвёртого.'),
dict(n=9, pts=1.5, title='Длительность фильмов', topics='цикл, f-строка, // и %',
 text='В одной строке длительности фильмов в минутах, через пробел.\n\nДля каждого фильма напечатайте строку в формате `H ч M мин`, где `H` — целые часы, `M` — оставшиеся минуты. Фильмы — в порядке ввода, каждый с новой строки.',
 fin='Одна строка — минуты через пробел.', fout='По строке `H ч M мин` на каждый фильм.',
 pre='',
 inputs=[['95 120 200'],['59'],['60 61'],['180'],['45 90 135 1']],
 sol="minutes = input().split()\n\nfor m in minutes:\n    print(f'{int(m) // 60} ч {int(m) % 60} мин')\n",
 hint='Часы — `// 60`, минуты — `% 60`. Число бывает строкой, нужен `int`. Печатайте через f-строку.',
 idea='Для каждой длительности делим на 60 нацело (часы) и берём остаток (минуты).',
 steps=['`minutes` — список **строк**, берём `int(m)`.','`int(m) // 60` — целые часы, `int(m) % 60` — остаток минут.','f-строка подставляет оба значения в шаблон `H ч M мин`.'],
 mist=['Забыли `int`: `//` и `%` со строкой — ошибка.','Поставили `/` вместо `//`: часы получатся дробными.','Напечатали все фильмы одной строкой: нужен отдельный `print` на каждый.'],
 trace='95 минут: 95 // 60 = 1, 95 % 60 = 35 → `1 ч 35 мин`. 120: 2 и 0 → `2 ч 0 мин`. 200: 3 и 20.'),
dict(n=10, pts=1.5, title='Рейтинг блюд', topics='while True, словарь-накопитель, sorted и lambda',
 text='Вводятся строки вида `блюдо,порций` (число порций — целое **положительное**), пока не будет введено слово `END`. Одно блюдо может встретиться несколько раз.\n\nНапечатайте блюда по **убыванию** суммарного числа порций, при равенстве — по алфавиту. Каждое — с новой строки в виде `блюдо порций`.',
 fin='Строки `блюдо,порций`, последняя строка — `END`.', fout='Строки `блюдо порций`.',
 pre='',
 inputs=[['борщ,10','суп,15','борщ,10','чай,5','END'],['пицца,7','END'],['б,10','а,10','в,3','END'],['чай,5','кофе,5','чай,1','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    dish, count = line.split(',')\n    if dish in totals:\n        totals[dish] += int(count)\n    else:\n        totals[dish] = int(count)\n\nfor dish, count in sorted(totals.items(), key=lambda x: (-x[1], x[0])):\n    print(dish, count)\n",
 hint='Сначала накопите суммы в словаре, как в предыдущих задачах. Потом `sorted(totals.items(), key=lambda x: (-x[1], x[0]))`.',
 idea='Сначала словарь «блюдо → порций», потом сортировка пар: минус перед числом даёт убывание, второе значение кортежа — алфавит при равенстве.',
 steps=['`totals = {}` — до цикла.','Если блюдо уже есть, прибавляем `totals[dish] += int(count)`, иначе создаём запись.','`totals.items()` — пары (блюдо, порций).','`key=lambda x: (-x[1], x[0])` — сначала по убыванию порций, потом по алфавиту.','`print(dish, count)` — через пробел.'],
 mist=['Забыли `-` перед `x[1]`: порядок будет по возрастанию.','Сортировка только по значению: при равенстве порядок блюд не алфавитный.','Забыли `int(count)`: строки склеиваются, а не складываются.'],
 trace='Борщ: 10 + 10 = 20, суп: 15, чай: 5. По убыванию: борщ 20, суп 15, чай 5.'),
]
